    <script>
        (() => { const regionBase = @json(route('regions', ['level' => 'provinces'])); const province = document.getElementById('profile-province-code'); const regency = document.getElementById('profile-regency-code'); const district = document.getElementById('profile-district-code'); if (!province || !regency || !district) return; const endpoint = (level, code = '') => `${regionBase.replace('/provinces', `/${level}`)}${code ? `/${encodeURIComponent(code)}` : ''}`; const setOptions = (select, items, placeholder, selectedCode) => { select.replaceChildren(new Option(placeholder, ''), ...items.map(item => new Option(item.name, item.code))); select.disabled = false; if (selectedCode) select.value = selectedCode; }; const load = async (url, select, placeholder, selectedCode) => { select.disabled = true; select.replaceChildren(new Option('Memuat data...', '')); try { const response = await fetch(url, { headers: { Accept: 'application/json' } }); if (!response.ok) throw new Error('Gagal memuat wilayah'); setOptions(select, (await response.json()).data ?? [], placeholder, selectedCode); } catch (error) { select.replaceChildren(new Option('Wilayah tidak dapat dimuat', '')); } }; const syncName = (select, inputId) => { document.getElementById(inputId).value = select.options[select.selectedIndex]?.text ?? ''; }; province.addEventListener('change', async () => { syncName(province, 'profile-province-name'); regency.replaceChildren(new Option('Pilih provinsi terlebih dahulu', '')); district.replaceChildren(new Option('Pilih kabupaten/kota terlebih dahulu', '')); regency.disabled = true; district.disabled = true; if (province.value) await load(endpoint('regencies', province.value), regency, 'Pilih kabupaten/kota', ''); }); regency.addEventListener('change', async () => { syncName(regency, 'profile-regency-name'); district.replaceChildren(new Option('Pilih kabupaten/kota terlebih dahulu', '')); district.disabled = true; if (regency.value) await load(endpoint('districts', regency.value), district, 'Pilih kecamatan', ''); }); district.addEventListener('change', () => syncName(district, 'profile-district-name')); load(endpoint('provinces'), province, 'Pilih provinsi', province.dataset.selectedCode).then(async () => { if (province.value) { await load(endpoint('regencies', province.value), regency, 'Pilih kabupaten/kota', regency.dataset.selectedCode); if (regency.value) await load(endpoint('districts', regency.value), district, 'Pilih kecamatan', district.dataset.selectedCode); } }); })();
        document.getElementById('avatar')?.addEventListener('change',()=>document.getElementById('avatar-submit')?.click());
    </script>
